/* Prefiks: trennbar = tekanan pada prefiks, terlepas di Präsens; untrennbar = be-, emp-, ent-, er-, ge-, miss-, ver-, zer- (tidak terlepas, partisip tanpa ge-) */
const DTM={pf:'Pilih prefiks (trennbar + untrennbar)',pe:'Bentuk Perfekt',zu:'zu-Infinitiv',tu:'Trennbar / untrennbar'};
let dtA=null;
function dtAll(){if(dtA)return dtA;dtA=[];const mk=(s,t)=>{const a=s.split('|'),ss=[];for(let i=5;i+1<a.length;i+=2)ss.push({s:a[i],tr:a[i+1]});dtA.push({inf:a[0],t,pre:a[1],ar:a[2],perf:a[3],zu:a[4],ss})};DTV.forEach(s=>mk(s,'T'));DTU.forEach(s=>mk(s,'U'));return dtA}
const dtFull=t=>t.s.replace(/[{}]/g,''),dtBlank=t=>t.s.split(/\{[^}]+\}/),dtStem=x=>x.inf.slice(x.pre.length);
/* DTR: untuk tiap stem, prefiks untrennbar yang membentuk kata Jerman NYATA (be-, emp-, ent-, er-, ge-, miss-, ver-, zer-). Pengecoh untrennbar hanya diambil dari luar daftar ini, sehingga tak pernah menjadi jawaban benar kedua (mis. stellen: be/ent/er/ver semua nyata). Stem yang tidak terdaftar tidak mendapat pengecoh untrennbar. */
const DTR={};'kommen:be ent ver|suchen:be ver er|zahlen:be|ginnen:be|antworten:be ver|stellen:be ent er ver|stehen:be ent er ge ver|sprechen:be ent ver|schreiben:be ver|nutzen:be ver|deuten:be miss|sichtigen:be|halten:be ent er ver|fehlen:be emp|fangen:emp ver be|finden:emp be er|schuldigen:ent be|decken:ent be ver|scheiden:ent be ver|wickeln:ent ver be|fernen:ent|klären:er ver|zählen:er ver|leben:er be ver ent|fahren:er be ver zer|reichen:er ge|lauben:er|kennen:er be ver|warten:er|fallen:ge be ent ver zer miss|hören:ge er ver|winnen:ge|lingen:ge miss|verstehen:miss|gessen:ver|lieren:ver|kaufen:ver er|binden:ver ent|ändern:ver|reisen:ver be|bringen:ver|dienen:ver be|missen:ver|stören:zer ver ent|reißen:zer ent|brechen:zer er ver|grüßen:be|gleiten:be ent|merken:be ver|obachten:be|richten:be er ent ver|weisen:be er ver|enden:be ver|lassen:ent be er ver zer|täuschen:ent|wähnen:er|ledigen:er ent|setzen:er be ent ver zer|höhen:er|lernen:er|nießen:ge|schehen:ge|trauen:miss ver be|bessern:ver|bieten:ver ge er ent|gleichen:ver be|passen:ver|schieben:ver|schwinden:ver ent|schneiden:zer ver be'.split('|').forEach(z=>{const[a,b]=z.split(':');DTR[a]=b.split(' ')});
/* Prefiks yang bisa trennbar SEKALIGUS untrennbar (umfahren, übersetzen …): tidak pernah dipakai sebagai pengecoh */
/* DTX: stem produktif (kommen, gehen …) hampir selalu bisa dipasangi prefiks trennbar apa pun; prefiks berikut membentuk verba nyata walau tak ada di data → dilarang sebagai pengecoh. DTG: keluarga arah yang saling tumpang-tindih (her/hin/…): jika jawabannya salah satunya, seluruh keluarga dilarang jadi pengecoh. */
const DTX={};'kommen:an ab auf aus ein mit nach vor zu weg zurück los weiter zusammen hoch herunter heraus hinaus herein vorbei her hin hinzu bei um fest|gehen:an ab auf aus ein mit nach vor zu weg zurück los weiter zusammen hoch herunter heraus hinaus herein vorbei her hin hinzu um fest|fahren:an ab auf aus ein mit nach vor zu weg zurück los weiter zusammen hoch herunter heraus hinaus herein vorbei her hin um fest|nehmen:an ab auf aus ein mit nach vor zu weg zurück fest herunter heraus hinaus herein her hin hinzu hoch teil um zusammen vorbei|geben:an ab auf aus ein mit nach vor zu weg zurück her hin weiter zusammen heraus bei statt hinzu hoch herunter hinaus herein um|machen:an ab auf aus ein mit nach vor zu weg zurück fest her hin los weiter zusammen hoch herunter heraus hinaus herein um vorbei hinzu|stellen:an ab auf aus ein mit nach vor zu weg zurück fest her hin zusammen hoch herunter heraus hinaus herein bei um los weiter vorbei hinzu|sehen:an ab auf aus ein mit nach vor zu weg zurück fern her hin weiter zusammen hoch herunter heraus hinaus herein vorbei um hinzu los fest|setzen:an ab auf aus ein mit nach vor zu weg zurück fest her hin zusammen hoch herunter heraus hinaus herein um weiter bei hinzu los|ziehen:an ab auf aus ein mit nach vor zu weg zurück fest her hin zusammen hoch herunter heraus hinaus herein um weiter bei hinzu vorbei los'.split('|').forEach(z=>{const[a,b]=z.split(':');DTX[a]=b.split(' ')});
const DTG=['her','hin','heraus','hinaus','herein','herunter','hinzu','hoch'];
const DTA=['um','durch','über','unter','hinter','wider','wieder','voll'],DTUP=['be','emp','ent','er','ge','miss','ver','zer'];
const dtSafeU=x=>{const s=dtStem(x),r=DTR[s];if(!r)return[];const inf=dtAll().map(z=>z.inf);return DTUP.filter(p=>p!=x.pre&&!r.includes(p)&&!inf.includes(p+s))};
function dtPfOpts(x){const all=dtAll(),inf=all.map(z=>z.inf),s=dtStem(x),tp=[...new Set(all.filter(z=>z.t=='T').map(z=>z.pre))].filter(p=>p!=x.pre&&!DTA.includes(p)&&!inf.includes(p+s)&&!(x.t=='T'&&((DTX[s]||[]).includes(p)||(DTG.includes(x.pre)&&DTG.includes(p)))));
 /* trennbar: pengecoh = prefiks trennbar lain + prefiks untrennbar (tidak pernah terlepas di akhir klausa). untrennbar: pengecoh = prefiks untrennbar yang pasti bukan kata + prefiks trennbar (tidak pernah menempel di klausa utama) */
 const uu=x.t=='T'?gxShuf(DTUP.filter(p=>p!=x.pre&&!inf.includes(p+s))):gxShuf(dtSafeU(x)),nu=x.t=='T'?2:3,tt=gxShuf(tp);let u=uu.slice(0,nu),t=tt.slice(0,5-u.length);
 if(x.t=='T'&&u.length+t.length<5)u=uu.slice(0,5-t.length);/* stem produktif: sedikit prefiks trennbar aman → tambah pengecoh untrennbar */
 return gxShuf([x.pre].concat(u,t))}
function dtPerfOpts(x){const [aux,pp]=x.perf.split(' '),c=[];
 if(aux=='ist')c.push('hat '+pp);
 c.push(aux+' ge'+pp);c.push(aux+' '+x.inf);c.push(aux+' ge'+x.inf);c.push(aux+' '+pp.replace(/(en|t)$/,'')+'et');
 c.push(aux+' '+(pp.endsWith('en')?pp.slice(0,-2)+'t':pp.endsWith('t')?pp.slice(0,-1)+'en':pp+'t'));
 const out=[];for(const o of gxShuf(c))if(o!=x.perf&&!out.includes(o)&&out.length<4)out.push(o);return gxShuf([x.perf].concat(out))}
function dtZuOpts(x){const r=dtStem(x),c=x.t=='T'?['zu '+x.inf,'zu'+x.inf,x.inf+' zu',x.pre+' zu '+r,x.pre+'zu '+r]:['zu'+x.inf,x.inf+' zu',x.pre+' zu '+r,'zu '+r];
 const out=[];for(const o of gxShuf(c))if(o!=x.zu&&!out.includes(o)&&out.length<4)out.push(o);return gxShuf([x.zu].concat(out))}
function dtCells(){const o=GXO('dtv'),c=[];for(const m of o.modes)for(const x of dtAll()){c.push({k:'dv|'+m+'|'+x.inf,m,x})}return c}
function dtMake(cell){const x=cell.x,m=cell.m,t=gxRnd(x.ss),full=dtFull(t),kind=x.t=='T'?'trennbar':'untrennbar',base={g:'dtv',k:cell.k,x,L:'de'};
 const ex=`${esc(full)} — ${esc(t.tr)}`,head=`<b>${esc(x.inf)}</b> = ${esc(x.ar)} (${kind})`;
 if(m=='pf'){const bl=dtBlank(t),T=x.t=='T',mk=(t.s.match(/\{([^}]+)\}/)||[])[1]||x.pre,C=p=>mk!=mk.toLowerCase()?p[0].toUpperCase()+p.slice(1):p;/* awal kalimat: opsi berhuruf kapital (Be-suchst du…?) */return Object.assign(base,{cell:'Verba Jerman · pilih prefiks',blanks:[{lab:'Prefiks yang tepat',opts:dtPfOpts(x).map(C),ok:[C(x.pre)],soft:[]}],parts:[bl[0],0,bl[1]||''],tr:t.tr,expl:`${head}<br>Infinitiv: ${esc(x.inf)} → prefiks <b>${esc(x.pre)}</b> ${T?'terlepas di Präsens (di akhir klausa)':'tidak bertekanan, menempel pada verba (tidak terlepas); partisip tanpa ge-'}.`,fullTxt:full,say:()=>full})}
 if(m=='pe')return Object.assign(base,{cell:'Verba Jerman · bentuk Perfekt',blanks:[{lab:'Perfekt (er/sie/es)',opts:dtPerfOpts(x),ok:[x.perf],soft:[]}],parts:[`${x.inf} — ${x.ar}`],tr:'',expl:`${head}<br>Perfekt: <b>${esc(x.perf)}</b><br>${ex}`,fullTxt:`${x.inf} → ${x.perf}`,say:()=>x.perf});
 if(m=='zu')return Object.assign(base,{cell:'Verba Jerman · zu-Infinitiv',blanks:[{lab:'zu-Infinitiv',opts:dtZuOpts(x),ok:[x.zu],soft:[]}],parts:[`${x.inf} — ${x.ar}`],tr:'',expl:`${head}<br>zu-Infinitiv: <b>${esc(x.zu)}</b><br>${ex}`,fullTxt:`${x.inf} → ${x.zu}`,say:()=>x.zu});
 return Object.assign(base,{cell:'Verba Jerman · trennbar atau untrennbar',blanks:[{lab:'Jenis verba',opts:['trennbar','untrennbar'],ok:[kind],soft:[]}],parts:[`${x.inf} — ${x.ar}`],tr:'',expl:`${head}<br>${x.t=='T'?`Prefiks <b>${esc(x.pre)}-</b> bertekanan dan terlepas di Präsens, partisip memakai -ge-.`:`Prefiks <b>${esc(x.pre)}-</b> tidak bertekanan dan tidak terlepas; partisip tanpa ge-.`}<br>${ex}`,fullTxt:`${x.inf}: ${kind}`,say:()=>x.inf})}
